import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  Input,
} from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  CustomTextArea,
  Loading,
} from "../../../../components";
import { useFormik } from "formik";
import useApi from "../../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

import "dayjs/locale/en-gb";
import { Modal } from "antd";
import { useStateContext } from "../../../../contexts/ContextProvider";
import servicesApi from "../../../../api/servicesApi";
import hospitalsApi from "../../../../api/hospitals/hospitalsApi";
import departmentsApi from "../../../../api/departmentsApi";

export default function EntityPhysiotherapyServicesFormModal({
  ismodalOpen,
  setisModalOpen,
  selectedPhysiotherapyService,
  modalTitle = "Add new retail inventory",
  updated,
  setUpdated,
}) {
  const moment = require("moment");
  const { currentColor, loggedInUser } = useStateContext()


  const [errors, setErrors] = useState();


  useEffect(() => {
    if (loggedInUser) {
      getDepartments();
    }
  }, [loggedInUser]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);


  const entityLaboratoryServicesApi = useApi(hospitalsApi.hospitalStaffAction)
  const handleLaboratoryServiceAction = async (data) => {

    await entityLaboratoryServicesApi.request(data)
  }


  useEffect(() => {
    if (entityLaboratoryServicesApi.data) {
      if (entityLaboratoryServicesApi.data.entity_physiotherapy_service) {
        toast.success(entityLaboratoryServicesApi.data.response_message)
        setUpdated(true)
        setisModalOpen(false)
      }


      if (entityLaboratoryServicesApi.data.errors) {
        setErrors(entityLaboratoryServicesApi.data.errors)
      }
    }
  }, [entityLaboratoryServicesApi.data])

  const formik = useFormik({
    initialValues: {

      charge: selectedPhysiotherapyService ? selectedPhysiotherapyService.charge : "",
      title: selectedPhysiotherapyService ? selectedPhysiotherapyService.title : "",
      physiotherapy_service: selectedPhysiotherapyService ? {label:selectedPhysiotherapyService.physiotherapy_service_title, value: selectedPhysiotherapyService.physiotherapy_service} : "",

    },

    validationSchema: Yup.object({
      charge: Yup.string().required().label("Title"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      let data = null;

      if (selectedPhysiotherapyService) {
        data = {
          "action": "UpdateEntityPhysiotherapyService",
          "entity_physiotherapy_service": selectedPhysiotherapyService.id,
          "charge": values.charge,
        }
      } else {
        data = {
          "action": "CreateEntityPhysiotherapyService",
          "physiotherapy_service": values.physiotherapy_service.value,
          "department": values.department.value,
          "charge": values.charge
        }
        console.log("data",data)

      }
      handleLaboratoryServiceAction(data)
      // resetForm();
    },
  });




  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  //Search laboratory services

  const searchPhysiotherapyServicesApi = useApi(hospitalsApi.hospitalStaffAction);

  const searchPhysiotherapyServices = async (data) => {
    await searchPhysiotherapyServicesApi.request(data);
  };
  const [physiotherapyServices, setphysiotherapyServices] = useState();
  const loadPhysiotherapyServicesOptions = async (inputText = "", callback) => {
    searchPhysiotherapyServices({
      action: "SearchPhysiotherapyServices",
      searchQuery: inputText,
    });
    callback(physiotherapyServices.map((i) => ({ label: i.title, value: i.id })));
  };

  useEffect(() => {
    if (searchPhysiotherapyServicesApi.data) {
      
      if (searchPhysiotherapyServicesApi.data.length) {
        setphysiotherapyServices(searchPhysiotherapyServicesApi.data);
      } else {
        setphysiotherapyServices([])
      }
    }
    console.log("searchProductsApi.data", searchPhysiotherapyServicesApi.data);
  }, [searchPhysiotherapyServicesApi.data]);

  //Retrieve departments
  const [departments, setDepartments] = useState([]);
  const departmentsActionsApi = useApi(departmentsApi.departmentsAction);
  const getDepartments = async () => {
    await departmentsActionsApi.request({
      action: "GetEntityDepartments",
      entity: loggedInUser.entity_id,
    });
  };

  useEffect(() => {
    if (departmentsActionsApi.data && departmentsActionsApi.data.length) {
      setDepartments(
        departmentsActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("departmentsActionsApi.data", departmentsActionsApi.data);
  }, [departmentsActionsApi.data]);




  return (
    <div className="w-full">
      <Modal
        width={600}
        className="w-full text-center"
        title={selectedPhysiotherapyService ? `EDIT ${selectedPhysiotherapyService.title}` : modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <div className="w-full grid grid-cols-1 mt-5 gap-1 ">

            <CustomFormItem
              touched={formik.touched.physiotherapy_service}
              error={formik.errors.physiotherapy_service}
            >
              <CustomSelectAsyncSelect
                className="text-start"
                name="physiotherapy_service"
                id="physiotherapy_service"
                label="Select physiotherapy service"
                size="large"
                onChange={(value) => formik.setFieldValue("physiotherapy_service", value)}
                value={formik.values.physiotherapy_service}
                placeholder="Select physiotherapy service"
                loadOptions={loadPhysiotherapyServicesOptions}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.department}
              error={formik.errors.department}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="department"
                id="department"
                label="Select department"
                size="large"
                onChange={(value) => formik.setFieldValue("department", value)}
                value={formik.values.department}
                placeholder="Select department"
                options={departments}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.charge}
              error={formik.errors.charge}
            >
              <CustomInput
                className="uppercase"
                required={true}
                label="Enter charge"
                id="charge"
                name="charge"
                onChange={formik.handleChange}
                placeholder="Enter charge"
                size="large"
                type="text"
                value={formik.values.charge}
              />
            </CustomFormItem>

          </div>
          <div className="w-full items-center mt-2">
            <Button style={{ background: currentColor }} className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
